+++ b/tests/sites.test.js
@@ -0,0 +1,53 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+test("site headers scope batches, quantities, alerts and value while sharing items", async () => {
+  const { store, handle } = app();
+  store.data.batches.push({ ...store.data.batches[0], id: 10, location: "annex-fridge", qty: 2, expires: "2026-10-29" });
+  const get = (path, headers) => handle({ path, headers });
+  assert.equal((await get("/batches")).body.length, 9);
+  assert.deepEqual((await get("/batches", annex)).body.map((b) => b.id), [10]);
+  assert.equal((await get("/batches/1", annex)).body.error.code, "unknown_batch");
+  assert.equal((await get("/batches/10")).body.error.code, "unknown_batch");
+  assert.equal((await get("/items/1", annex)).body.onHand, 2);
+  assert.equal((await get("/items/1")).body.onHand, 10);
+  assert.equal((await get("/items", annex)).body.length, store.data.items.length);
+  assert.equal((await get("/reports/stock-value", annex)).body.totalCents, 360);
+  const alerts = (await get("/alerts", annex)).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [10]);
+  assert.equal(alerts.lowStock.find((i) => i.itemId === 1).qty, 2);
+  assert.equal((await get("/batches", { "x-larder-site": "annex" })).body.length, 1);
+  const unknown = await get("/items", { "x-larder-site": "missing" });
+  assert.equal(unknown.status, 400);
+  assert.equal(unknown.body.error.code, "unknown_site");
+});
+
+test("cooking and waste cannot use another site's stock", async () => {
+  const { store, handle } = app();
+  const before = structuredClone(store.data);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } })).status, 409);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: annex, body: { qty: 1 } })).status, 404);
+  assert.deepEqual(store.data, before);
+});
+
+test("stock-takes and receiving enforce site locations and ids", async () => {
+  const { store, handle } = app();
+  const post = (path, body, headers = annex) => handle({ method: "POST", path, body, headers });
+  assert.equal((await post("/stocktakes", { location: "fridge" })).body.error.code, "unknown_location");
+  const take = (await post("/stocktakes", { location: "annex-fridge" })).body;
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {}, {})).status, 404);
+  store.data.batches.push({ ...store.data.batches[0], id: 10, location: "annex-fridge", qty: 2 });
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId: 1, counted: 0 })).status, 404);
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId: 10, counted: 1 })).status, 200);
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {})).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 1);
+  assert.equal(store.data.batches[0].qty, 4);
+  const before = structuredClone(store.data);
+  assert.equal((await post("/orders/2/receive", { lots: [
+    { lot: "a", location: "annex-fridge" }, { lot: "b", location: "fridge" },
+  ] })).body.error.code, "unknown_location");
+  assert.deepEqual(store.data, before);
+});
